//! Parity tests for the `pi_js::vendor::jsdiff::util` helpers.
//!
//! `VECTORS` was generated by running the real `diff@8.0.4` (libesm/util) under Node 24.

use pi_js::vendor::jsdiff::util::distance_iterator::distance_iterator;
use pi_js::vendor::jsdiff::util::string::{
    has_only_unix_line_endings, has_only_win_line_endings, leading_and_trailing_ws, leading_ws, longest_common_prefix,
    longest_common_suffix, maximum_overlap, remove_prefix, remove_suffix, replace_prefix, replace_suffix, trailing_ws,
};
use serde_json::{Value, json};

fn outcome(result: pi_js::error::Result<String>) -> Value {
    match result {
        Ok(r) => json!({ "r": r }),
        Err(e) => json!({ "err": e.message(), "name": e.name() }),
    }
}

#[test]
fn util_functions_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(VECTORS).expect("vectors");
    let mut checked = 0;
    for (i, case) in cases.iter().enumerate() {
        checked += 1;
        match case["k"].as_str().expect("k") {
            "pair" => {
                let a = case["a"].as_str().expect("a");
                let b = case["b"].as_str().expect("b");
                assert_eq!(longest_common_prefix(a, b), case["lcp"], "case {i} lcp");
                assert_eq!(longest_common_suffix(a, b), case["lcs"], "case {i} lcs");
                assert_eq!(maximum_overlap(a, b), case["overlap"], "case {i} overlap");
                assert_eq!(
                    outcome(replace_prefix(a, b, "<P>")),
                    case["replacePrefix"],
                    "case {i} replacePrefix"
                );
                assert_eq!(
                    outcome(replace_suffix(a, b, "<S>")),
                    case["replaceSuffix"],
                    "case {i} replaceSuffix"
                );
                assert_eq!(
                    outcome(remove_prefix(a, b)),
                    case["removePrefix"],
                    "case {i} removePrefix"
                );
                assert_eq!(
                    outcome(remove_suffix(a, b)),
                    case["removeSuffix"],
                    "case {i} removeSuffix"
                );
            }
            "single" => {
                let s = case["s"].as_str().expect("s");
                assert_eq!(has_only_win_line_endings(s), case["win"], "case {i} win");
                assert_eq!(has_only_unix_line_endings(s), case["unix"], "case {i} unix");
                assert_eq!(leading_ws(s, None), case["leadingWs"], "case {i} leadingWs");
                assert_eq!(trailing_ws(s, None), case["trailingWs"], "case {i} trailingWs");
                let (lead, trail) = leading_and_trailing_ws(s, None);
                assert_eq!(
                    json!([lead, trail]),
                    case["leadingAndTrailingWs"],
                    "case {i} leadingAndTrailingWs"
                );
            }
            "distance" => {
                let it = distance_iterator(
                    case["start"].as_f64().expect("start"),
                    case["min"].as_f64().expect("min"),
                    case["max"].as_f64().expect("max"),
                );
                let seq: Vec<f64> = it.take(100).collect();
                let want: Vec<f64> = case["seq"]
                    .as_array()
                    .expect("seq")
                    .iter()
                    .map(|v| v.as_f64().expect("n"))
                    .collect();
                assert_eq!(seq, want, "case {i} distance");
            }
            other => panic!("unknown case kind {other}"),
        }
    }
    assert!(checked > 200);
}

